import { useCallback, useId, useMemo, useRef, useState } from 'react';
import { Button, Input } from '@jinx-ui/react';

export interface TagPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
  maxTags?: number;
  disabled?: boolean;
}

const SEPARATORS = /[,\n\t]/;

function normalize(raw: string): string {
  return raw.trim().replace(/\s+/g, ' ');
}

export default function TagPicker({
  value,
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  maxTags = 12,
  disabled = false,
}: TagPickerProps) {
  const inputId = useId();
  const hintId = `${inputId}-hint`;
  const inputRef = useRef<HTMLInputElement>(null);
  const [internal, setInternal] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');

  const isControlled = value !== undefined;
  const tags = isControlled ? value : internal;
  const isFull = tags.length >= maxTags;

  const commit = useCallback(
    (next: string[]) => {
      if (!isControlled) setInternal(next);
      onChange?.(next);
    },
    [isControlled, onChange],
  );

  const addFrom = useCallback(
    (raw: string) => {
      const candidates = raw
        .split(SEPARATORS)
        .map(normalize)
        .filter(Boolean);
      if (candidates.length === 0) return;

      const next = [...tags];
      for (const candidate of candidates) {
        if (next.length >= maxTags) break;
        const exists = next.some(
          (tag) => tag.toLowerCase() === candidate.toLowerCase(),
        );
        if (!exists) next.push(candidate);
      }
      if (next.length !== tags.length) commit(next);
      setDraft('');
    },
    [commit, maxTags, tags],
  );

  const removeAt = useCallback(
    (index: number) => {
      commit(tags.filter((_, i) => i !== index));
      inputRef.current?.focus();
    },
    [commit, tags],
  );

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addFrom(draft);
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      removeAt(tags.length - 1);
    }
  };

  const hint = useMemo(
    () =>
      isFull
        ? `Достигнут предел: ${maxTags} тегов`
        : `Enter или запятая — добавить тег. ${tags.length} из ${maxTags}`,
    [isFull, maxTags, tags.length],
  );

  return (
    <div className="jx-field jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
      <label className="jx-label" htmlFor={inputId}>
        {label}
      </label>

      <Input
        id={inputId}
        ref={inputRef}
        className="jx-input"
        value={draft}
        placeholder={isFull ? 'Лимит тегов исчерпан' : placeholder}
        disabled={disabled || isFull}
        aria-describedby={hintId}
        onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
          setDraft(event.target.value)
        }
        onKeyDown={handleKeyDown}
        onBlur={() => addFrom(draft)}
      />

      <p id={hintId} className="jx-text-muted jx-text-sm">
        {hint}
      </p>

      {tags.length > 0 && (
        <ul
          className="jx-cluster"
          aria-label="Выбранные теги"
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: 'var(--jx-space-2)',
            margin: 0,
            padding: 0,
            listStyle: 'none',
          }}
        >
          {tags.map((tag, index) => (
            <li
              key={tag.toLowerCase()}
              className="jx-badge"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 'var(--jx-space-1)',
                borderRadius: 'var(--jx-radius)',
              }}
            >
              <span>{tag}</span>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="jx-btn jx-btn-ghost"
                disabled={disabled}
                aria-label={`Удалить тег ${tag}`}
                onClick={() => removeAt(index)}
              >
                ×
              </Button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

